      proposal: { considered: [{ action: 'ASK_USER' }, { action: 'FINISH' }], selected: { action: 'FINISH' } },
      approval: { kind: 'approve', history: [{ kind: 'alternative', action: 'FINISH' }, { kind: 'approve' }] },
      toolResult: null, stateAfter: { currentGoal: 'Task complete.' },
    });
